request:
{
 "project": "E-GOVERNANCE MISSION MODE PROJECT (MMP) CRIME & CRIMINAL TRACKING NETWORK AND SYSTEMS (CCTNS) FUNCTIONAL REQUIREMENTS SPECIFICATION V1.0 (DRAFT) MINISTRY OF HOME AFFAIRS GOVERNMENT OF INDIA",
 "meeting": "1 of 1 (kickoff)",
 "participants": [
  "Analyst",
  "Client",
  "EndUser",
  "TechLead"
 ],
 "previous_turns_for_context_only": [
  {
   "speaker": "TechLead",
   "act": "state",
   "content": [
    "The user interfaces of the system should comply with Standard ISO 9241.",
    "Providing text equivalents for non-text media objects: All non-text media objects, such as graphical images or video, should be provided with alternative equivalent textual descriptions and/or with equivalent text-based functionality."
   ]
  },
  {
   "speaker": "Client",
   "act": "state",
   "content": [
    "Making navigation self-descriptive: Navigation should be designed to help users understand where they are, where they have been and where they can go next. General guidance on achieving self-descriptiveness is given in ISO 9241-110."
   ]
  },
  {
   "speaker": "Analyst",
   "act": "backchannel"
  }
 ],
 "turns": [
  {
   "id": "M1:T41",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Minimizing navigation effort: The number of navigation steps needed to reach a certain piece of content should be minimized as long as different mental models, navigation strategies and tasks of the user are taken into account.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T42",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Splash screens should be avoided unless they provide useful content or feedback about the application state to the user. If a splash screen is used, a navigation option to skip it should be offered.",
     "role": "statement"
    },
    {
     "text": "Avoiding opening unnecessary windows: Additional windows such as new browser windows or pop-up windows should only be opened if this supports the user's task. Opening new windows can distract, confuse or impede users for a variety of reasons. They can superimpose the primary window, hiding relevant information. They could make it cognitively more difficult to understand the navigation structure with negative effects on both usability and accessibility. They also require additional user actions for closing unwanted windows.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T43",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Making user interfaces robust: User interfaces should be designed to be as robust as possible in the face of changing technology. This encompasses being able to present content containing newer technologies by older user agents as well as designing content to be usable with future technologies.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T44",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T45",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Acceptable opening / download times: Application pages should be designed and implemented so that there are acceptable opening times and download times for the expected range of technical contexts of use (e.g. bandwidth between the application and the user). This is particularly important for frequently accessed pages or pages that are important for user navigation and exploration, such as the home page.",
     "role": "statement"
    },
    {
     "text": "Providing clear error messages: The content of error messages shown on the pages or special error pages should clearly state the reason why the error occurred and, if possible, actions the user can take to resolve the error. Users expect error messages to be in the same language as the user interface.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T46",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T47",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Text quality: The quality of textual content with respect to spelling and grammar should be sufficient so as not to impede readability.",
     "role": "statement"
    },
    {
     "text": "Distinguishable within-page links: Within-page links should be clearly distinguishable from other links that lead to a different page. EX. Within-page links are shown with dashed rather than solid underlines",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T48",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "Distinguishable within-page links: Within-page links should be clearly distinguishable from other links that lead to a different page. EX. Within-page links are shown with dashed rather than solid underlines",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T49",
   "speaker": "Client",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T50",
   "speaker": "Client",
   "act": "offtopic",
   "guide": "A brief off-topic remark typical of video calls (audio, screen sharing, schedule)."
  },
  {
   "id": "M1:T51",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Distinguishing navigation links from controls: Navigation links should be clearly distinguishable from controls activating some action. Typical action types in user interfaces include manipulating application data, performing searches, communication actions, such as opening a new e-mail window or starting a chat function, and presentation-related actions, such as sorting a list of search results.",
     "role": "statement"
    },
    {
     "text": "Providing printable document versions: If a document is either too long, dispersed over several pages or in a specific layout that is not suitable for online reading, a printer-friendly version of the document should be provided that prints the content in a form acceptable to the user (e.g. in the expected layout, paper format, or orientation).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T52",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Selecting appropriate page lengths The length of a page should be selected so as to support the primary purpose and use of the page. Short pages are generally more appropriate for homepages, navigation pages, or overview pages that need to be read quickly. Longer pages can be more appropriate when users want to read the content without interruptions or when the page needs to match a paper counterpart.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T53",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "Selecting appropriate page lengths The length of a page should be selected so as to support the primary purpose and use of the page. Short pages are generally more appropriate for homepages, navigation pages, or overview pages that need to be read quickly. Longer pages can be more appropriate when users want to read the content without interruptions or when the page needs to match a paper counterpart.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T54",
   "speaker": "Client",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T55",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Using frames with care: If frames are used, care should be taken to avoid possible problems, for example, those involving the use of the back button, bookmarking of pages, or scrolling of information. When frames are used, it is important to title each frame, and to describe its purpose and how frames relate to one another other.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T56",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Linking back to the home page or landmark pages: Each page should contain a link leading to the home page of the application or to a landmark page that is easy to recognize for the user.",
     "role": "statement"
    },
    {
     "text": "Providing a site map: A separate navigation overview such as a site map should be provided for application showing the structure of the site in an overview form.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T57",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "Providing a site map: A separate navigation overview such as a site map should be provided for application showing the structure of the site in an overview form.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T58",
   "speaker": "TechLead",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T59",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Placing navigation components consistently: Navigation components should be placed consistently on the pages or in the framesets in the pages of the application.",
     "role": "statement"
    },
    {
     "text": "Taking account of the users' tasks and information needs: When providing different access paths or navigation structures for different user groups, the tasks and information needs of these user groups should be taken into consideration.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T60",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Making individualization and adaptation evident: It should be made evident to the user when individualization and/or adaptation are used.",
     "role": "statement"
    },
    {
     "text": "Making user profiles evident: If predefined user profiles or user-specified profiles are used for individualizing or adapting content, the profile currently used should be made evident. If profiles are used, it is important to provide users with information about this concept and its implications.",
     "role": "statement"
    }
   ]
  }
 ]
}
